-- traditional_song 与 comment 都使用 NOT EXISTS 去重

USE [music_db_test];
GO

-- ===== 新歌曲 =====
IF OBJECT_ID('tempdb..#newsong') IS NOT NULL DROP TABLE #newsong;
GO
CREATE TABLE #newsong (
  [title] nvarchar(200) NOT NULL,
  [category_id] int NOT NULL,
  [genre] nvarchar(100) NOT NULL,
  [audio_url] nvarchar(500) NOT NULL,
  [cover_url] nvarchar(500) NOT NULL
);
GO

