DECLARE @song_base int = (SELECT ISNULL(MAX([id]),0) FROM [dbo].[traditional_song]);
;WITH new_songs AS (
  SELECT n.*, ROW_NUMBER() OVER (ORDER BY n.[category_id], n.[title]) AS rn
  FROM #newsong n
  WHERE NOT EXISTS (
    SELECT 1 FROM [dbo].[traditional_song] t
    WHERE t.[title] = n.[title] AND t.[category_id] = n.[category_id]
  )
)
INSERT INTO [dbo].[traditional_song] ([id],[title],[category_id],[genre],[audio_url],[cover_url])
SELECT @song_base + rn, [title],[category_id],[genre],[audio_url],[cover_url]
FROM new_songs;
GO

DROP TABLE #newsong;
GO

-- ===== 新评论 =====
IF OBJECT_ID('tempdb..#newcmt') IS NOT NULL DROP TABLE #newcmt;
GO
CREATE TABLE #newcmt (
  [song_title] nvarchar(200) NOT NULL,
  [category_id] int NOT NULL,
  [source] nvarchar(50) NOT NULL,
  [content] nvarchar(4000) NOT NULL,
  [likes] int NULL,
  [comment_time] date NULL
);
GO

