INSERT INTO #newcmt ([song_title],[category_id],[source],[content],[likes],[comment_time]) VALUES
(N'出水莲 (客家筝曲)', N'8', N'netease', N'也许你该在竹林听十面埋伏。虽然十面埋伏和竹林没啥关系。但想想电影中十面埋伏还是行的', N'17', N'2026-01-18'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'一秒就被评论破功。救命', N'17', N'2026-03-05'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'我一个05后天天听这些[大哭]', N'15', N'2025-02-04'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'悄悄把檀香换成蚊香，别人看不出来的[鬼脸]', N'13', N'2025-12-02'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'《出水莲》和《寒鸦戏水》、《平沙落雁》、《柳青娘》同为潮州音乐独奏曲中的“中国十大古筝名曲”之一，是潮州音乐（细乐[1]）中的筝乐名曲，是筝家必弹之曲目。中州古调，采用传统的十六弦钢丝筝演奏，音调古朴，风格淡雅，以一种特殊的韵味，别具一格的音乐，表现了莲花这种花中君子“出污泥而不染', N'12', N'2026-03-18'),
(N'出水莲 (客家筝曲)', N'8', N'bilibili', N'不过以前的古筝样式都被现在基本都被21弦筝代替了', N'11', N'2024-03-02'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'静，是一个人的修炼。因为懂得，所以慈悲，因为漂亮，所以宽容。因为，内心的从容和安定，是人生最曼妙的风景。在风起云涌间流转，我们只需沿着自己生命的轨迹安染前行，就能踱步未来。内心高贵的人，举手投足间会透露出自身的优雅，即使年华老去，行走在斑斓的岁月中，眼底依然会有星辰大海会。', N'11', N'2026-04-16'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远益清，亭亭净植，可远观而不可亵玩焉。', N'11', N'2024-09-19'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'同感同感[大笑]', N'11', N'2026-03-12'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'单曲循环好久好久[可爱][可爱][可爱][可爱]', N'11', N'2024-08-27'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'秦声半瑟造韶虞，
汉筑千家变调弦。
古曲清扬龙越海，
筝然逸响凤鸣天。', N'10', N'2025-10-01'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'还别说，2014年的时候，我在优酷看到一个改编自林海的琵琶语的吉他独奏曲，太好听了，我……一时冲动买了一把吉他……', N'9', N'2026-08-07'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'确实，我也同感，不知道自己喜欢的音乐风格为什么总跟朋友们格格不入，他们一听这种歌就皱个眉，明明很好听', N'9', N'2025-07-18'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'被老师夸过弹的有灵性的一首曲子。。也好多年了。古筝也老早放掉了。', N'9', N'2024-07-18'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'很好的爱好呀。这些都是国乐的精华，人家古人从小就开始学习啦。', N'9', N'2025-01-29'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'花花娇欲语，愁杀荡舟人。----李白', N'8', N'2026-08-28'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'《出水莲》（古筝中国）中国十大古筝名曲之一,一曲实际上是借景抒怀、言志，全曲着意表现莲花“出自污泥而不染”的纯洁、高尚情操。由于表情艺术具有表演性和形象性的特点，表情艺术都包括一度和二度创作，依赖于二度创作。音乐形象的塑造也需要演员演奏演唱，所以同一首曲不同演员演奏也会有不同风格', N'7', N'2024-07-05'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'出水莲
清香漫
碧天夏至渐凉
花芳双眸艳
筝声声
思君念

~✨✨🌿🌈', N'7', N'2024-06-24'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'竟然没有人在说左手要废了吗，这首歌升4降7，上下滑音和颤音平均一句三四次，又难把音摁准。反正我现在左手还有点抖。', N'7', N'2025-01-05'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'最喜欢王昌元老师演奏的版本，很遗憾网上搜不到着个谱，不知道哪位筝友有珍藏。', N'7', N'2024-02-07'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'我也是22岁的小伙子，我也喜欢这样的曲子，很喜欢', N'7', N'2024-06-21'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'小时候可喜欢听古筝曲了，那时是录音机加磁带翻来覆去的听，听曲时总幻想自己很优雅地在抚琴，人生过半，看来抚琴是梦想了，更别说优雅了。哈哈，听听也不错，感谢网易云。', N'7', N'2025-04-10'),
(N'出水莲 (客家筝曲)', N'8', N'bilibili', N'琵琶的出水莲也好听，特别喜欢', N'6', N'2025-12-04'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'《出水莲》是潮州音乐啊！不是客家的。潮汕与客家完全是两个不同的概念！', N'6', N'2025-11-03'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'坐在客家围龙屋的天井里，看到雨滴打到水缸中的睡莲上，着到此曲，就是这种意境。', N'6', N'2025-05-09'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'这么久过去了，你的古筝还好不？

跟你说个笑话我也想买一个古筝[大哭][大哭]', N'6', N'2024-09-23'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'可以听听江上清风游', N'6', N'2024-03-16'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'《出水莲》和《寒鸦戏水》、《平沙落雁》、《柳青娘》同为潮州音乐独奏曲中的中国十大古筝名曲之一，通常用古筝中的客家筝（也叫潮州筝）演奏。所以……', N'6', N'2024-06-08'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'555，你为什么干不过一楼[大哭]', N'6', N'2024-08-30'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'音乐的美在这可以感受到的', N'5', N'2024-04-17'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'看着挺容易的，实际好难，没那个闲时间练习啊，荒废了', N'5', N'2026-08-25'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'关键词“一时冲动', N'5', N'2025-11-27'),
(N'出水莲 (客家筝曲)', N'8', N'netease', N'出水莲弹起来远比听起来难的多，记得这是我们当时七级考级曲目之一，很多节奏和速度还有感情都很难掌握，现在再听依然可以依稀记得被老师说哭的悲伤[流感][流感]', N'5', N'2025-08-12'),
