INSERT INTO #newcmt ([song_title],[category_id],[source],[content],[likes],[comment_time]) VALUES
(N'葬心', N'13', N'bilibili', N'这首歌真的很好听，以前就会唱，觉得很独特，才知道原来是阮玲玉主题曲[脸红]', N'23', N'2026-04-16'),
(N'葬心', N'13', N'bilibili', N'感谢阿婆主 我知道不知道该如何表达对此歌曲的痴迷 小虫和黄莺莺真的是太有才了 简直是珠联璧合 相得益彰！[脱单doge]', N'21', N'2024-06-29'),
(N'葬心', N'13', N'bilibili', N'我才十六岁，感觉对这首歌真的没有代沟，太爱了，配上阮玲玉凄惨唯美的民国往事，真的觉得太过于厉害', N'20', N'2025-11-08'),
(N'葬心', N'13', N'netease', N'我心目中最美的伦巴舞曲。', N'17', N'2026-01-06'),
(N'葬心', N'13', N'bilibili', N'小虫说过谱曲的时候好像听到阮和他说话，唉，可怜的人。', N'16', N'2025-11-14'),
(N'葬心', N'13', N'netease', N'别口嗨你口水一个', N'15', N'2025-10-25'),
(N'葬心', N'13', N'netease', N'小虫真的太牛逼了 这个编曲简直是神 神仙才能编出的曲', N'15', N'2025-12-18'),
(N'葬心', N'13', N'bilibili', N'这么好视频太少人看了', N'13', N'2024-07-20'),
(N'葬心', N'13', N'netease', N'写这首歌曲之前，小虫从未去过大陆，全靠研究大量资料，创作出具有30年代老上海味道的曲子。在录制《葬心》的30年代版《野草闲花蓬春生》和《长叹》时，小虫先把黑胶唱片放在地上磨蹭，再录回去，制造“沙沙”的怀旧复古感；并要求黄莺莺用夹子夹住鼻子，唱出30年代歌星的嗓音特质；最后再用单轨收音，', N'13', N'2024-09-01'),
(N'葬心', N'13', N'bilibili', N'阿译的bgm', N'12', N'2025-06-10'),
(N'葬心', N'13', N'bilibili', N'阿译这调调没问题啊，不能说一模一样，至少也是精髓到了', N'11', N'2025-11-20'),
(N'葬心', N'13', N'netease', N'试机，绝佳', N'11', N'2024-04-21'),
(N'葬心', N'13', N'bilibili', N'重返乐园里王慧唱的歌', N'10', N'2025-04-13'),
(N'葬心', N'13', N'bilibili', N'他如果有罪，那么我也想要犯下同样的错', N'9', N'2025-08-22'),
(N'葬心', N'13', N'bilibili', N'张曼玉演的阮玲玉，真的不如阮玲玉', N'9', N'2024-10-12'),
(N'葬心', N'13', N'bilibili', N'这个电影每次看到女主角自尽，歌声响起时，都让我泪流满面，不能自己。😭', N'9', N'2025-09-25'),
(N'葬心', N'13', N'netease', N'几干套？', N'9', N'2025-01-21'),
(N'葬心', N'13', N'netease', N'这个录得还一般，有幸拿到一版黑胶，虽然有底噪，但整个听下来就感觉真人站你面前唱的一样，音也比这一版生动', N'9', N'2025-11-10'),
(N'葬心', N'13', N'bilibili', N'这首歌是不是还有一个名字叫《闲花野草逢春生》，不知道为什么被传的很恐怖', N'8', N'2026-03-03'),
(N'葬心', N'13', N'netease', N'宣传需要罢了', N'8', N'2024-09-20'),
