INSERT INTO #newcmt ([song_title],[category_id],[source],[content],[likes],[comment_time]) VALUES
(N'太阳出来喜洋洋(四川民歌)', N'26', N'netease', N'就在小学。。。。。。我们还是血气方刚的孩子。。。。。。一天，班主任和我们说，过几天领导来视察，不上课了，跳舞，我们也都很高兴，都很感谢领导，可是就在音乐响起时我们都在想：去nm的领导', N'3', N'2026-06-23'),
(N'太阳出来喜洋洋(四川民歌)', N'26', N'netease', N'小学音乐课学过', N'3', N'2025-09-03'),
(N'巴山夜雨紛紛', N'26', N'netease', N'来自道长的《八分》。。[拜]', N'125', N'2026-07-27'),
(N'巴山夜雨紛紛', N'26', N'netease', N'记忆里第一次听还是16年在常德出差，沅江边停靠的小船，氤氲的水汽。作为北方人，第一次感受南方湿冷的冬天和碧绿的江水。21年冬天终于到了大巴山旁出差，却遗憾没能找到白水老师这首歌。现在终于回来了。', N'105', N'2024-06-03'),
(N'巴山夜雨紛紛', N'26', N'netease', N'十六年前我还年轻时在songtaste上听到这首歌，当时就惊为天人。后来豆瓣fm上、虾米上也经常听。现在我老了，这三个平台也早已是风流云散。', N'72', N'2025-05-29'),
(N'巴山夜雨紛紛', N'26', N'netease', N'想起来伟大的诗人，好像总是郁郁不得志，史书里的人生也是总有遗憾不得圆满。或许故土总该是要远离的，这是命也是运。想念我回不去的巴山夜雨。', N'28', N'2025-09-25'),
(N'巴山夜雨紛紛', N'26', N'netease', N'何当共剪西窗烛，却话巴山夜雨时。', N'15', N'2025-07-01'),
(N'巴山夜雨紛紛', N'26', N'netease', N'而今听雨僧庐下，鬓已星星也。悲欢离合总无情，一任阶前、点滴到天明。', N'12', N'2024-07-06'),
(N'巴山夜雨紛紛', N'26', N'netease', N'终于能听到了，08、09年大学的时候很喜欢听白水的民谣', N'9', N'2025-09-18'),
(N'巴山夜雨紛紛', N'26', N'netease', N'这是四川话嘛，为什么听得像古语，透露出古韵的沧桑和悲壮感', N'9', N'2025-02-23'),
(N'巴山夜雨紛紛', N'26', N'netease', N'恍惚间又听到了陈升', N'9', N'2025-12-12'),
(N'巴山夜雨紛紛', N'26', N'netease', N'大三时把白水现场照挂qq空间。鲜有知音者。10年大学毕业。一晃15年。网易好地方。', N'8', N'2025-09-20'),
(N'巴山夜雨紛紛', N'26', N'netease', N'2010年第一次听时，他出国留学，我们不知道未来怎么样，能走到哪一天。 笑谈归时梦中泪，哪知相逢在何方。 现在我们结婚十年了，孩子不知道这首歌有什么好听的，爸爸妈妈总不删。', N'8', N'2024-01-03'),
(N'巴山夜雨紛紛', N'26', N'netease', N'飘飘乎遗世而独立，羽化而登仙', N'8', N'2026-01-06'),
(N'巴山夜雨紛紛', N'26', N'netease', N'这首歌我听了12年', N'8', N'2024-07-12'),
(N'巴山夜雨紛紛', N'26', N'netease', N'我的故乡正在巴山脚下，母亲和舅舅在这里弹吉他、离开，在死去后又回来。而我已经到了这么远的地方', N'7', N'2024-10-07'),
(N'巴山夜雨紛紛', N'26', N'netease', N'天呐 我在网易云听到了什么！ 白水竟然回归了！ ！ 一晃13年了……13年前单曲循环在一个人去唐模的路上……', N'7', N'2024-06-07'),
(N'巴山夜雨紛紛', N'26', N'netease', N'每一个下雨的山城夜晚 都想听巴山夜雨纷纷', N'7', N'2026-02-21'),
(N'巴山夜雨紛紛', N'26', N'netease', N'雨下了四五天了，适合睡觉 更适合思念故人 阴雨绵绵，思绪冗长 三杯小酒，两行清泪 独吾一人难眠', N'7', N'2024-07-03'),
(N'巴山夜雨紛紛', N'26', N'netease', N'深夜，台风，上海，八分。', N'7', N'2024-08-03'),
(N'巴山夜雨紛紛', N'26', N'netease', N'终于有版权了，妈耶', N'7', N'2025-08-24'),
(N'巴山夜雨紛紛', N'26', N'youtube', N'十年前听过没有忘，十年后身在异国找到这儿来终于又听上了 ; )', N'6', N'2024-11-13'),
(N'巴山夜雨紛紛', N'26', N'netease', N'最后的女声伴唱是点睛之笔，隔空挂念的惆怅感', N'6', N'2024-06-20'),
(N'巴山夜雨紛紛', N'26', N'netease', N'宜宾老表来报道，我是说听(一)ye (六)lue (七)qie (十)sei那么熟悉呢哈哈哈。弄过起读，还是乡音听着舒服呢', N'6', N'2024-07-03'),
(N'巴山夜雨紛紛', N'26', N'netease', N'女声袁田老师，天鹅与花朵', N'6', N'2024-07-20'),
(N'巴山夜雨紛紛', N'26', N'netease', N'这竖笛太美了  在下雨的重庆听 一定会流泪', N'6', N'2025-07-13'),
(N'巴山夜雨紛紛', N'26', N'netease', N'萧声太强烈了，它可是回到某个过去的瞬间也可以是通向未来，此刻也可以，只是灵魂抽空飘起', N'6', N'2025-01-21'),
(N'巴山夜雨紛紛', N'26', N'netease', N'朋友们，美人吟回来了！！！', N'6', N'2026-04-29'),
(N'巴山夜雨紛紛', N'26', N'netease', N'最爱这首，像古琴的感觉，很有古意', N'6', N'2025-01-05'),
(N'巴山夜雨紛紛', N'26', N'netease', N'期待花拾叁楼主人', N'6', N'2024-05-08'),
(N'巴山夜雨紛紛', N'26', N'netease', N'翻看以前签名：她的脚步已远去，回头看不到。却始终记不起来是什么出处，搜索才发现是白水的歌。签名时间为2009，一眼十余年，时光如水，终也不再是少年。', N'5', N'2024-08-01'),
(N'巴山夜雨紛紛', N'26', N'netease', N'四川资中人在家养伤.每天都听白水大神的歌曲.听白水的歌有种让我安静思考的力量.每天心情也好一点', N'5', N'2025-11-05'),
(N'巴山夜雨紛紛', N'26', N'netease', N'是清明节专属吧 听了好舒服，有种尸体spa的感觉', N'5', N'2024-02-11'),
(N'巴山夜雨紛紛', N'26', N'netease', N'鸿雁飞到巴蜀该算是白鹭吧', N'5', N'2026-03-27'),
(N'巴山夜雨紛紛', N'26', N'netease', N'外面在下雨就突然想听听歌，推荐第一首', N'5', N'2026-03-13'),
(N'巴山夜雨紛紛', N'26', N'netease', N'人生一梦梦十年，巴山夜夜听雨，雨纷纷。', N'5', N'2024-03-06'),
(N'巴山夜雨紛紛', N'26', N'netease', N'每次听，都更晓澈分别意。觉得万物仍在，只是心有余音。', N'5', N'2026-05-06'),
(N'巴山夜雨紛紛', N'26', N'netease', N'《雨》 下雨的时候灵魂在哭泣 2019.5.22海口', N'5', N'2025-05-09'),
(N'巴山夜雨紛紛', N'26', N'netease', N'chooselife', N'5', N'2024-09-16'),
(N'巴山夜雨紛紛', N'26', N'netease', N'君问归期未有期，巴山夜雨涨秋池。何当共剪西窗烛，却话巴山夜雨时。巴山楚水凄凉地，二十三年弃置身。怀旧空吟闻笛赋，到乡翻似烂柯人。关山难越，谁悲失路之人。萍水相逢，尽是他乡之客。', N'5', N'2026-07-15'),
