DECLARE @cmt_base int = (SELECT ISNULL(MAX([id]),0) FROM [dbo].[comment]);
;WITH cmt_with_sid AS (
  SELECT t.[id] AS song_id, n.[source], n.[content], n.[likes], n.[comment_time]
  FROM #newcmt n
  JOIN [dbo].[traditional_song] t
    ON t.[title] = n.[song_title] AND t.[category_id] = n.[category_id]
)
INSERT INTO [dbo].[comment] ([id],[song_id],[content],[likes],[source],[comment_time])
SELECT @cmt_base + ROW_NUMBER() OVER (ORDER BY song_id, [source], [content]),
       song_id, [content], [likes], [source], [comment_time]
FROM cmt_with_sid c
WHERE NOT EXISTS (
  SELECT 1 FROM [dbo].[comment] x
  WHERE x.[song_id]=c.[song_id] AND x.[source]=c.[source] AND x.[content]=c.[content]
);
GO

DROP TABLE #newcmt;
GO